import{_ as a,c as e,o as t,a2 as s}from"./chunks/framework.DdOM6S6U.js";const u=JSON.parse('{"title":"Migration Commands","description":"","frontmatter":{"sidebarPos":7,"sidebarTitle":"Overview","sidebarGroupTitle":"Migration"},"headers":[],"relativePath":"guide/console/migration/overview.md","filePath":"guide/console/migration/overview.md","lastUpdated":1778363927000}'),i={name:"guide/console/migration/overview.md"},r=s(`<h1 id="migration-commands" tabindex="-1">Migration Commands <a class="header-anchor" href="#migration-commands" aria-label="Permalink to &quot;Migration Commands&quot;">​</a></h1><p>Run Modularous-aware migrations. These wrap Laravel&#39;s migration commands with awareness of module directories — they scan <code>modules/*/Database/Migrations/</code> in addition to the host app&#39;s <code>database/migrations/</code>.</p><table><thead><tr><th>Command</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><a href="./migrate">migrate</a></td><td><code>modularous:migrate</code></td><td>Run all module migrations</td></tr><tr><td><a href="./migrate-refresh">migrate:refresh</a></td><td><code>modularous:migrate:refresh</code></td><td>Rollback and re-run all module migrations</td></tr><tr><td><a href="./migrate-rollback">migrate:rollback</a></td><td><code>modularous:migrate:rollback</code></td><td>Rollback the last batch of module migrations</td></tr></tbody></table><h2 id="common-workflows" tabindex="-1">Common Workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common Workflows&quot;">​</a></h2><h3 id="apply-new-migrations-during-development" tabindex="-1">Apply new migrations during development <a class="header-anchor" href="#apply-new-migrations-during-development" aria-label="Permalink to &quot;Apply new migrations during development&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:migrate</span></span></code></pre></div><p>Runs any unmigrated files across all modules. Safe to re-run; already-applied migrations are skipped.</p><h3 id="reset-and-re-seed-a-local-database" tabindex="-1">Reset and re-seed a local database <a class="header-anchor" href="#reset-and-re-seed-a-local-database" aria-label="Permalink to &quot;Reset and re-seed a local database&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:migrate:refresh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:seed</span></span></code></pre></div><p>Rolls back everything and migrates fresh. <strong>Never use on production</strong> — this drops data. Prefer <code>migrate:rollback</code> for targeted undo.</p><h3 id="revert-a-mistake" tabindex="-1">Revert a mistake <a class="header-anchor" href="#revert-a-mistake" aria-label="Permalink to &quot;Revert a mistake&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:migrate:rollback</span></span></code></pre></div><p>Rolls back the <strong>last batch</strong> of migrations. Run repeatedly to roll back further batches.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/get-started/upgrading">Upgrading</a> — migrations play a central role in version upgrades</li><li><a href="./../sync/sync-states">Sync / sync:states</a> — keep enum-backed state columns in sync after migrations</li><li><a href="./../check-collation">check-collation</a> — verify database collation settings</li></ul>`,15),o=[r];function n(l,d,h,c,p,m){return t(),e("div",null,o)}const k=a(i,[["render",n]]);export{u as __pageData,k as default};
